-- Dumpar data för tabell information_schema.SYSTEM_VARIABLES: -1 rows
/*!40000 ALTER TABLE `SYSTEM_VARIABLES` DISABLE KEYS */;
INSERT INTO `SYSTEM_VARIABLES` (`VARIABLE_NAME`, `SESSION_VALUE`, `GLOBAL_VALUE`, `GLOBAL_VALUE_ORIGIN`, `DEFAULT_VALUE`, `VARIABLE_SCOPE`, `VARIABLE_TYPE`, `VARIABLE_COMMENT`, `NUMERIC_MIN_VALUE`, `NUMERIC_MAX_VALUE`, `NUMERIC_BLOCK_SIZE`, `ENUM_VALUE_LIST`, `READ_ONLY`, `COMMAND_LINE_ARGUMENT`, `GLOBAL_VALUE_PATH`) VALUES
	('BINLOG_GTID_INDEX_PAGE_SIZE', NULL, '4096', 'COMPILE-TIME', '4096', 'GLOBAL', 'INT UNSIGNED', 'Page size to use for the binlog GTID index.', '64', '16777216', '1', NULL, 'NO', 'REQUIRED', NULL),
	('LOG_TC_SIZE', NULL, '24576', 'AUTO', '24576', 'GLOBAL', 'BIGINT UNSIGNED', 'Size of transaction coordinator log.', '12288', '18446744073709551615', '4096', NULL, 'YES', 'REQUIRED', NULL),
	('SQL_MODE', '', 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION', 'COMPILE-TIME', 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION', 'SESSION', 'SET', 'Sets the sql mode', NULL, NULL, NULL, 'REAL_AS_FLOAT,PIPES_AS_CONCAT,ANSI_QUOTES,IGNORE_SPACE,IGNORE_BAD_TABLE_OPTIONS,ONLY_FULL_GROUP_BY,NO_UNSIGNED_SUBTRACTION,NO_DIR_IN_CREATE,POSTGRESQL,ORACLE,MSSQL,DB2,MAXDB,NO_KEY_OPTIONS,NO_TABLE_OPTIONS,NO_FIELD_OPTIONS,MYSQL323,MYSQL40,ANSI,NO_AUTO_VALUE_ON_ZERO,NO_BACKSLASH_ESCAPES,STRICT_TRANS_TABLES,STRICT_ALL_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ALLOW_INVALID_DATES,ERROR_FOR_DIVISION_BY_ZERO,TRADITIONAL,NO_AUTO_CREATE_USER,HIGH_NOT_PRECEDENCE,NO_ENGINE_SUBSTITUTION,PAD_CHAR_TO_FULL_LENGTH,EMPTY_STRING_IS_NULL,SIMULTANEOUS_ASSIGNMENT,TIME_ROUND_FRACTIONAL', 'NO', 'REQUIRED', NULL),
	('BINLOG_FORMAT', 'MIXED', 'MIXED', 'COMPILE-TIME', 'MIXED', 'SESSION', 'ENUM', 'What form of binary logging the master will use: either ROW for row-based binary logging, STATEMENT for statement-based binary logging, or MIXED. MIXED is statement-based binary logging except for those statements where only row-based is correct: those which involve user-defined functions (i.e. UDFs) or the UUID() function; for those, row-based binary logging is automatically used.', NULL, NULL, NULL, 'MIXED,STATEMENT,ROW', 'NO', 'REQUIRED', NULL),
	('BINLOG_SPACE_LIMIT', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'Alias for max_binlog_total_size. Compatibility with Percona server.', '0', '18446744073709551615', '1', NULL, 'NO', 'REQUIRED', NULL),
	('PERFORMANCE_SCHEMA_EVENTS_WAITS_HISTORY_SIZE', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'BIGINT', 'Number of rows per thread in EVENTS_WAITS_HISTORY. Use 0 to disable, -1 for automated sizing.', '-1', '1024', '1', NULL, 'YES', 'REQUIRED', NULL),
	('AUTOMATIC_SP_PRIVILEGES', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Creating and dropping stored procedures alters ACLs', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('PERFORMANCE_SCHEMA_MAX_COND_CLASSES', NULL, '90', 'COMPILE-TIME', '90', 'GLOBAL', 'BIGINT UNSIGNED', 'Maximum number of condition instruments.', '0', '256', '1', NULL, 'YES', 'REQUIRED', NULL),
	('READ_ONLY', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Make all non-temporary tables read-only, with the exception for replication (slave) threads and users with the \'READ ONLY ADMIN\' privilege', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('PERFORMANCE_SCHEMA_MAX_COND_INSTANCES', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'BIGINT', 'Maximum number of instrumented condition objects. Use 0 to disable, -1 for automated sizing.', '-1', '1048576', '1', NULL, 'YES', 'REQUIRED', NULL),
	('INNODB_FLUSH_LOG_AT_TIMEOUT', NULL, '1', 'COMPILE-TIME', '1', 'GLOBAL', 'INT UNSIGNED', 'Write and flush logs every (n) second.', '0', '2700', '0', NULL, 'NO', 'OPTIONAL', NULL),
	('PERFORMANCE_SCHEMA_MAX_RWLOCK_INSTANCES', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'BIGINT', 'Maximum number of instrumented RWLOCK objects. Use 0 to disable, -1 for automated sizing.', '-1', '104857600', '1', NULL, 'YES', 'REQUIRED', NULL),
	('INNODB_ENCRYPT_TEMPORARY_TABLES', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Enrypt the temporary table data.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL', NULL),
	('PERFORMANCE_SCHEMA_MAX_PREPARED_STATEMENTS_INSTANCES', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'BIGINT', 'Maximum number of instrumented prepared statements. Use 0 to disable, -1 for automated scaling.', '-1', '1048576', '1', NULL, 'YES', 'REQUIRED', NULL),
	('DISCONNECT_ON_EXPIRED_PASSWORD', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'This variable controls how the server handles clients that are not aware of the sandbox mode. If enabled, the server disconnects the client, otherwise the server puts the client in a sandbox mode.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('PERFORMANCE_SCHEMA_EVENTS_WAITS_HISTORY_LONG_SIZE', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'BIGINT', 'Number of rows in EVENTS_WAITS_HISTORY_LONG. Use 0 to disable, -1 for automated sizing.', '-1', '1048576', '1', NULL, 'YES', 'REQUIRED', NULL),
	('GTID_BINLOG_POS', NULL, '', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Last GTID logged to the binary log, per replicationdomain', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('PERFORMANCE_SCHEMA_MAX_MUTEX_INSTANCES', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'BIGINT', 'Maximum number of instrumented MUTEX objects. Use 0 to disable, -1 for automated sizing.', '-1', '104857600', '1', NULL, 'YES', 'REQUIRED', NULL),
	('LOG_DISABLED_STATEMENTS', 'sp', 'sp', 'COMPILE-TIME', 'sp', 'SESSION', 'SET', 'Don\'t log certain types of statements to general log', NULL, NULL, NULL, 'slave,sp', 'NO', 'REQUIRED', NULL),
	('TIME_ZONE', '+00:00', 'SYSTEM', 'COMPILE-TIME', 'SYSTEM', 'SESSION', 'VARCHAR', 'The current time zone, used to initialize the time zone for a client when it connects. Set to SYSTEM by default, in which the client uses the system time zone value.', NULL, NULL, NULL, NULL, 'NO', NULL, NULL),
	('INNODB_STATS_TRANSIENT_SAMPLE_PAGES', NULL, '8', 'COMPILE-TIME', '8', 'GLOBAL', 'INT UNSIGNED', 'The number of leaf index pages to sample when calculating transient statistics (if persistent statistics are not used, default 8)', '1', '4294967295', '0', NULL, 'NO', 'REQUIRED', NULL),
	('HAVE_CRYPT', NULL, 'YES', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'If the crypt() system call is available this variable will be set to YES, otherwise it will be set to NO. If set to NO, the ENCRYPT() function cannot be used.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('SLOW_LAUNCH_TIME', NULL, '2', 'COMPILE-TIME', '2', 'GLOBAL', 'BIGINT UNSIGNED', 'If creating the thread takes longer than this value (in seconds), the Slow_launch_threads counter will be incremented', '0', '31536000', '1', NULL, 'NO', 'REQUIRED', NULL),
	('PERFORMANCE_SCHEMA_MAX_RWLOCK_CLASSES', NULL, '50', 'COMPILE-TIME', '50', 'GLOBAL', 'BIGINT UNSIGNED', 'Maximum number of rwlock instruments.', '0', '256', '1', NULL, 'YES', 'REQUIRED', NULL),
	('LOG_SLOW_MAX_WARNINGS', '10', '10', 'COMPILE-TIME', '10', 'SESSION', 'BIGINT UNSIGNED', 'Max numbers of warnings printed to slow query log per statement', '0', '1000', '1', NULL, 'NO', 'REQUIRED', NULL),
	('PERFORMANCE_SCHEMA_MAX_SOCKET_CLASSES', NULL, '10', 'COMPILE-TIME', '10', 'GLOBAL', 'BIGINT UNSIGNED', 'Maximum number of socket instruments.', '0', '256', '1', NULL, 'YES', 'REQUIRED', NULL),
	('INNODB_ADAPTIVE_HASH_INDEX_PARTS', NULL, '8', 'COMPILE-TIME', '8', 'GLOBAL', 'BIGINT UNSIGNED', 'Number of InnoDB Adaptive Hash Index Partitions (default 8)', '1', '512', '0', NULL, 'YES', 'OPTIONAL', NULL),
	('PERFORMANCE_SCHEMA_ACCOUNTS_SIZE', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'BIGINT', 'Maximum number of instrumented user@host accounts. Use 0 to disable, -1 for automated sizing.', '-1', '1048576', '1', NULL, 'YES', 'REQUIRED', NULL),
	('THREAD_POOL_OVERSUBSCRIBE', NULL, '3', 'COMPILE-TIME', '3', 'GLOBAL', 'INT UNSIGNED', 'How many additional active worker threads in a group are allowed.', '1', '1000', '1', NULL, 'NO', 'REQUIRED', NULL),
	('CONCURRENT_INSERT', NULL, 'AUTO', 'COMPILE-TIME', 'AUTO', 'GLOBAL', 'ENUM', 'Use concurrent insert with MyISAM', NULL, NULL, NULL, 'NEVER,AUTO,ALWAYS', 'NO', 'OPTIONAL', NULL),
	('GTID_STRICT_MODE', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Enforce strict seq_no ordering of events in the binary log. Slave stops with an error if it encounters an event that would cause it to generate an out-of-order binlog if executed. When ON the same server-id semisync-replicated transactions that duplicate existing ones in binlog are ignored without error and slave interruption.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('WSREP_IGNORE_APPLY_ERRORS', NULL, '7', 'COMPILE-TIME', '7', 'GLOBAL', 'INT UNSIGNED', 'Ignore replication errors', '0', '7', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_FT_NUM_WORD_OPTIMIZE', NULL, '2000', 'COMPILE-TIME', '2000', 'GLOBAL', 'BIGINT UNSIGNED', 'InnoDB Fulltext search number of words to optimize for each optimize table call ', '1000', '10000', '0', NULL, 'NO', 'OPTIONAL', NULL),
