	('DELAY_KEY_WRITE', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'ENUM', 'Specifies how MyISAM tables handles CREATE TABLE DELAY_KEY_WRITE. If set to ON, the default, any DELAY KEY WRITEs are honored. The key buffer is then flushed only when the table closes, speeding up writes. MyISAM tables should be automatically checked upon startup in this case, and --external locking should not be used, as it can lead to index corruption. If set to OFF, DELAY KEY WRITEs are ignored, while if set to ALL, all new opened tables are treated as if created with DELAY KEY WRITEs enabled.', NULL, NULL, NULL, 'OFF,ON,ALL', 'NO', 'OPTIONAL', NULL),
	('SQL_AUTO_IS_NULL', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'If set to 1, the query SELECT * FROM table_name WHERE auto_increment_column IS NULL will return an auto-increment that has just been successfully inserted, the same as the LAST_INSERT_ID() function. Some ODBC programs make use of this IS NULL comparison.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL, NULL),
