	('VERSION_COMMENT', NULL, 'mariadb.org binary distribution', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Value of the COMPILATION_COMMENT option specified by CMake when building MariaDB, for example mariadb.org binary distribution.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
