	('KEY_CACHE_FILE_HASH_SIZE', NULL, '512', 'COMPILE-TIME', '512', 'GLOBAL', 'BIGINT UNSIGNED', 'Number of hash buckets for open and changed files.  If you have a lot of MyISAM files open you should increase this for faster flush of changes. A good value is probably 1/10 of number of possible open MyISAM files.', '128', '16384', '1', NULL, 'NO', 'REQUIRED', NULL),
