	('SLAVE_DDL_EXEC_MODE', NULL, 'IDEMPOTENT', 'COMPILE-TIME', 'IDEMPOTENT', 'GLOBAL', 'ENUM', 'How replication events should be executed. Legal values are STRICT and IDEMPOTENT (default). In IDEMPOTENT mode, replication will not stop for DDL operations that are idempotent. This means that CREATE TABLE is treated as CREATE TABLE OR REPLACE and DROP TABLE is treated as DROP TABLE IF EXISTS.', NULL, NULL, NULL, 'STRICT,IDEMPOTENT', 'NO', 'REQUIRED', NULL),
	('HOST_CACHE_SIZE', NULL, '653', 'AUTO', '128', 'GLOBAL', 'BIGINT UNSIGNED', 'How many host names should be cached to avoid resolving.', '0', '65536', '1', NULL, 'NO', 'REQUIRED', NULL),
	('GTID_CURRENT_POS', NULL, '', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Current GTID position of the server. Per replication domain, this is either the last GTID replicated by a slave thread, or the GTID logged to the binary log, whichever is most recent.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('INNODB_MAX_PURGE_LAG', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'Desired maximum length of the purge queue (0 = no limit)', '0', '18446744073709551615', '0', NULL, 'NO', 'REQUIRED', NULL),
	('HAVE_OPENSSL', NULL, 'YES', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Comparing have_openssl with have_ssl will indicate whether YaSSL or openssl was used. If YaSSL, have_ssl will be YES, but have_openssl will be NO.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('MYISAM_MAX_SORT_FILE_SIZE', NULL, '9223372036853727232', 'COMPILE-TIME', '9223372036853727232', 'GLOBAL', 'BIGINT UNSIGNED', 'Don\'t use the fast sort index method to created index if the temporary file would get bigger than this', '0', '9223372036854775807', '1048576', NULL, 'NO', 'REQUIRED', NULL),
	('VERSION_COMPILE_MACHINE', NULL, 'x86_64', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'The machine type or architecture MariaDB was built on, for example i686.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('INNODB_LRU_SCAN_DEPTH', NULL, '1536', 'COMPILE-TIME', '1536', 'GLOBAL', 'BIGINT UNSIGNED', 'How deep to scan LRU to keep it clean', '100', '18446744073709551615', '0', NULL, 'NO', 'REQUIRED', NULL),
