	('BINLOG_STMT_CACHE_SIZE', NULL, '32768', 'COMPILE-TIME', '32768', 'GLOBAL', 'BIGINT UNSIGNED', 'The size of the statement cache for updates to non-transactional engines for the binary log. If you often use statements updating a great number of rows, you can increase this to get more performance.', '4096', '18446744073709551615', '4096', NULL, 'NO', 'REQUIRED', NULL),
	('OLD_MODE', 'UTF8_IS_UTF8MB3', 'UTF8_IS_UTF8MB3', 'COMPILE-TIME', 'UTF8_IS_UTF8MB3', 'SESSION', 'SET', 'Used to emulate old behavior from earlier MariaDB or MySQL versions', NULL, NULL, NULL, 'NO_DUP_KEY_WARNINGS_WITH_IGNORE,NO_PROGRESS_INFO,ZERO_DATE_TIME_CAST,UTF8_IS_UTF8MB3,IGNORE_INDEX_ONLY_FOR_JOIN,COMPAT_5_1_CHECKSUM,NO_NULL_COLLATION_IDS,LOCK_ALTER_TABLE_COPY', 'NO', 'REQUIRED', NULL),
