	('DEFAULT_REGEX_FLAGS', '', '', 'COMPILE-TIME', '', 'SESSION', 'SET', 'Default flags for the regex library', NULL, NULL, NULL, 'DOTALL,DUPNAMES,EXTENDED,EXTENDED_MORE,EXTRA,MULTILINE,UNGREEDY', 'NO', 'REQUIRED', NULL),
	('BULK_INSERT_BUFFER_SIZE', '8388608', '8388608', 'COMPILE-TIME', '8388608', 'SESSION', 'BIGINT UNSIGNED', 'Size of tree cache used in bulk insert optimisation. Note that this is a limit per thread!', '0', '18446744073709551615', '1', NULL, 'NO', 'REQUIRED', NULL),
	('HISTOGRAM_TYPE', 'JSON_HB', 'JSON_HB', 'COMPILE-TIME', 'JSON_HB', 'SESSION', 'ENUM', 'Specifies type of the histograms created by ANALYZE. Possible values are: SINGLE_PREC_HB - single precision height-balanced, DOUBLE_PREC_HB - double precision height-balanced, JSON_HB - height-balanced, stored as JSON.', NULL, NULL, NULL, 'SINGLE_PREC_HB,DOUBLE_PREC_HB,JSON_HB', 'NO', 'REQUIRED', NULL),
	('TMP_TABLE_SIZE', '67108864', '67108864', 'CONFIG', '16777216', 'SESSION', 'BIGINT UNSIGNED', 'Alias for tmp_memory_table_size. If an internal in-memory temporary table exceeds this size, MariaDB will automatically convert it to an on-disk MyISAM or Aria table.', '0', '18446744073709551615', '16384', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_DATA_FILE_WRITE_THROUGH', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Whether each write to data files writes through', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('THREAD_HANDLING', NULL, 'one-thread-per-connection', 'COMPILE-TIME', 'one-thread-per-connection', 'GLOBAL', 'ENUM', 'Define threads usage for handling queries', NULL, NULL, NULL, 'one-thread-per-connection,no-threads,pool-of-threads', 'YES', 'REQUIRED', NULL),
	('INNODB_USE_ATOMIC_WRITES', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Enable atomic writes, instead of using the doublewrite buffer, for files on devices that supports atomic writes.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'NONE', NULL),
	('QUERY_CACHE_TYPE', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'ENUM', 'OFF = Don\'t cache or retrieve results. ON = Cache all results except SELECT SQL_NO_CACHE ... queries. DEMAND = Cache only SELECT SQL_CACHE ... queries', NULL, NULL, NULL, 'OFF,ON,DEMAND', 'NO', 'REQUIRED', NULL),
	('PROXY_PROTOCOL_NETWORKS', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Enable proxy protocol for these source networks. The syntax is a comma separated list of IPv4 and IPv6 networks. If the network doesn\'t contain mask, it is considered to be a single host. "*" represents all networks and must the only directive on the line. String "localhost" represents non-TCP local connections (Unix domain socket, Windows named pipe or shared memory).', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED', NULL),
	('VERSION_MALLOC_LIBRARY', NULL, 'system', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Version of the used malloc library', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('INNODB_DOUBLEWRITE', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'ENUM', 'Whether and how to use the doublewrite buffer. OFF=Assume that writes of innodb_page_size are atomic; ON=Prevent torn writes (the default); fast=Like ON, but do not synchronize writes to data files', NULL, NULL, NULL, 'OFF,ON,fast', 'NO', 'OPTIONAL', NULL),
	('GTID_SLAVE_POS', NULL, '', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'The list of global transaction IDs that were last replicated on the server, one for each replication domain.', NULL, NULL, NULL, NULL, 'NO', NULL, NULL),
	('INNODB_STATS_PERSISTENT', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'InnoDB persistent statistics enabled for all tables unless overridden at table level', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('MAX_SP_RECURSION_DEPTH', '0', '0', 'COMPILE-TIME', '0', 'SESSION', 'BIGINT UNSIGNED', 'Maximum stored procedure recursion depth', '0', '255', '1', NULL, 'NO', 'OPTIONAL', NULL),
	('DEFAULT_WEEK_FORMAT', '0', '0', 'COMPILE-TIME', '0', 'SESSION', 'BIGINT UNSIGNED', 'The default week format used by WEEK() functions', '0', '7', '1', NULL, 'NO', 'REQUIRED', NULL),
	('REPORT_PORT', NULL, '3306', 'AUTO', '0', 'GLOBAL', 'INT UNSIGNED', 'Port for connecting to slave reported to the master during slave registration. Set it only if the slave is listening on a non-default port or if you have a special tunnel from the master or other clients to the slave. If not sure, leave this option unset', '0', '4294967295', '1', NULL, 'YES', 'REQUIRED', NULL),
	('ARIA_PAGECACHE_FILE_HASH_SIZE', NULL, '512', 'COMPILE-TIME', '512', 'GLOBAL', 'BIGINT UNSIGNED', 'Number of hash buckets for open and changed files.  If you have a lot of Aria files open you should increase this for faster flush of changes. A good value is probably 1/10 of number of possible open Aria files.', '128', '16384', '1', NULL, 'YES', 'REQUIRED', NULL),
	('RELAY_LOG', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'The location and name to use for relay logs.', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
	('INNODB_DEFAULT_ROW_FORMAT', NULL, 'dynamic', 'COMPILE-TIME', 'dynamic', 'GLOBAL', 'ENUM', 'The default ROW FORMAT for all innodb tables created without explicit ROW_FORMAT. Possible values are REDUNDANT, COMPACT, and DYNAMIC. The ROW_FORMAT value COMPRESSED is not allowed', NULL, NULL, NULL, 'redundant,compact,dynamic', 'NO', 'REQUIRED', NULL),
	('FT_MAX_WORD_LEN', NULL, '84', 'COMPILE-TIME', '84', 'GLOBAL', 'BIGINT UNSIGNED', 'The maximum length of the word to be included in a FULLTEXT index. Note: FULLTEXT indexes must be rebuilt after changing this variable', '10', '84', '1', NULL, 'YES', 'REQUIRED', NULL),
	('INNODB_USE_NATIVE_AIO', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Use native AIO if supported on this platform.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'NONE', NULL),
	('WSREP_MODE', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'SET', 'Set of WSREP features that are enabled.', NULL, NULL, NULL, 'STRICT_REPLICATION,BINLOG_ROW_FORMAT_ONLY,REQUIRED_PRIMARY_KEY,REPLICATE_MYISAM,REPLICATE_ARIA,DISALLOW_LOCAL_GTID,BF_ABORT_MARIABACKUP', 'NO', 'REQUIRED', NULL),
	('OPTIMIZER_TRACE_MAX_MEM_SIZE', '1048576', '1048576', 'COMPILE-TIME', '1048576', 'SESSION', 'BIGINT UNSIGNED', 'Maximum allowed size of an optimizer trace', '0', '18446744073709551615', '1', NULL, 'NO', 'REQUIRED', NULL),
	('BINLOG_COMMIT_WAIT_COUNT', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'If non-zero, binlog write will wait at most binlog_commit_wait_usec microseconds for at least this many commits to queue up for group commit to the binlog. This can reduce I/O on the binlog and provide increased opportunity for parallel apply on the slave, but too high a value will decrease commit throughput.', '0', '18446744073709551615', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_UNDO_TABLESPACES', NULL, '3', 'COMPILE-TIME', '3', 'GLOBAL', 'INT UNSIGNED', 'Number of undo tablespaces to use.', '0', '127', '0', NULL, 'YES', 'REQUIRED', NULL),
	('BINLOG_EXPIRE_LOGS_SECONDS', NULL, '864000', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'If non-zero, binary logs will be purged after binlog_expire_logs_seconds seconds; It and expire_logs_days are linked, such that changes in one are converted into the other. Possible purges happen at startup and at binary log rotation.', '0', '8553600', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_BUF_DUMP_STATUS_FREQUENCY', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'A number between [0, 100] that tells how oftern buffer pool dump status in percentages should be printed. E.g. 10 means that buffer pool dump status is printed when every 10% of number of buffer pool pages are dumped. Default is 0 (only start and end status is printed).', '0', '100', '0', NULL, 'NO', 'REQUIRED', NULL),
	('ANALYZE_SAMPLE_PERCENTAGE', '100.000000', '100.000000', 'COMPILE-TIME', '100.000000', 'SESSION', 'DOUBLE', 'Percentage of rows from the table ANALYZE TABLE will sample to collect table statistics. Set to 0 to let MariaDB decide what percentage of rows to sample.', '0', '100', NULL, NULL, 'NO', 'REQUIRED', NULL),
	('DEADLOCK_SEARCH_DEPTH_SHORT', '4', '4', 'COMPILE-TIME', '4', 'SESSION', 'BIGINT UNSIGNED', 'Short search depth for the two-step deadlock detection', '0', '32', '1', NULL, 'NO', 'REQUIRED', NULL),
