	('THREAD_CACHE_SIZE', NULL, '256', 'COMPILE-TIME', '256', 'GLOBAL', 'BIGINT UNSIGNED', 'How many threads we should keep in a cache for reuse. These are freed after 5 minutes of idle time', '0', '16384', '1', NULL, 'NO', 'REQUIRED', NULL),
	('SERVER_ID', '1', '1', 'CONFIG', '1', 'SESSION', 'BIGINT UNSIGNED', 'Uniquely identifies the server instance in the community of replication partners', '1', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
