	('BINLOG_LEGACY_EVENT_POS', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Fill in the end_log_pos field of _all_ events in the binlog, even when doing so costs performance. Can be used in case some old application needs it for backwards compatibility. Setting this option can hurt binlog scalability.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
