	('TX_ISOLATION', 'REPEATABLE-READ', 'REPEATABLE-READ', 'COMPILE-TIME', 'REPEATABLE-READ', 'SESSION', 'ENUM', 'Default transaction isolation level.This variable is deprecated and will be removed in a future release.', NULL, NULL, NULL, 'READ-UNCOMMITTED,READ-COMMITTED,REPEATABLE-READ,SERIALIZABLE', 'NO', NULL, NULL),
	('BINLOG_OPTIMIZE_THREAD_SCHEDULING', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Run fast part of group commit in a single thread, to optimize kernel thread scheduling. On by default. Disable to run each transaction in group commit in its own thread, which can be slower at very high concurrency. This option is mostly for testing one algorithm versus the other, and it should not normally be necessary to change it.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'REQUIRED', NULL),
