	('EXPENSIVE_SUBQUERY_LIMIT', '100', '100', 'COMPILE-TIME', '100', 'SESSION', 'BIGINT UNSIGNED', 'The maximum number of rows a subquery may examine in order to be executed during optimization and used for constant optimization', '0', '18446744073709551615', '1', NULL, 'NO', 'REQUIRED', NULL),
	('OPTIMIZER_JOIN_LIMIT_PREF_RATIO', '0', '0', 'COMPILE-TIME', '0', 'SESSION', 'BIGINT UNSIGNED', 'For queries with JOIN and ORDER BY LIMIT : make the optimizer consider a join order that allows to short-cut execution after producing #LIMIT matches if that promises N times speedup. (A conservative setting here would be is a high value, like 100 so the short-cutting plan is used if it promises a speedup of 100x or more). Short-cutting plans are inherently risky so the default is 0 which means do not consider this optimization', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_BUFFER_POOL_DUMP_AT_SHUTDOWN', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Dump the buffer pool into a file named @@innodb_buffer_pool_filename', NULL, NULL, NULL, 'OFF,ON', 'NO', 'REQUIRED', NULL),
	('BINLOG_DO_DB', NULL, '', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Tells the primary it should log updates for the specified database, and exclude all others not explicitly mentioned.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('SSL_CRLPATH', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'CRL directory (check OpenSSL docs, implies --ssl)', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
	('SLAVE_MAX_STATEMENT_TIME', NULL, '0.000000', 'COMPILE-TIME', '0.000000', 'GLOBAL', 'DOUBLE', 'A query that has taken more than slave_max_statement_time seconds to run on the slave will be aborted. The argument will be treated as a decimal value with microsecond precision. A value of 0 (default) means no timeout', '0', '31536000', NULL, NULL, 'NO', 'REQUIRED', NULL),
	('DEADLOCK_SEARCH_DEPTH_LONG', '15', '15', 'COMPILE-TIME', '15', 'SESSION', 'BIGINT UNSIGNED', 'Long search depth for the two-step deadlock detection', '0', '33', '1', NULL, 'NO', 'REQUIRED', NULL),
	('NET_BUFFER_LENGTH', '16384', '16384', 'COMPILE-TIME', '16384', 'SESSION', 'BIGINT UNSIGNED', 'Buffer length for TCP/IP and socket communication', '1024', '1048576', '1024', NULL, 'NO', 'REQUIRED', NULL),
	('MRR_BUFFER_SIZE', '262144', '262144', 'COMPILE-TIME', '262144', 'SESSION', 'BIGINT UNSIGNED', 'Size of buffer to use when using MRR with range access', '8192', '2147483647', '1', NULL, 'NO', 'REQUIRED', NULL),
	('SYNC_BINLOG', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT UNSIGNED', 'Synchronously flush binary log to disk after every #th event. Use 0 (default) to disable synchronous flushing', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_MAX_DIRTY_PAGES_PCT_LWM', NULL, '0.000000', 'COMPILE-TIME', '0.000000', 'GLOBAL', 'DOUBLE', 'Percentage of dirty pages at which flushing kicks in. The value 0 (default) means \'refer to innodb_max_dirty_pages_pct\'.', '0', '99.999', NULL, NULL, 'NO', 'REQUIRED', NULL),
	('TABLE_DEFINITION_CACHE', NULL, '400', 'AUTO', '400', 'GLOBAL', 'BIGINT UNSIGNED', 'The number of cached table definitions', '400', '2097152', '1', NULL, 'NO', 'REQUIRED', NULL),
	('OPTIMIZER_ROW_NEXT_FIND_COST', NULL, '0.045916', 'COMPILE-TIME', '0.045916', 'GLOBAL', 'DOUBLE', 'Cost of finding the next row when scanning the table.', '0', '1000', NULL, NULL, 'NO', 'REQUIRED', NULL),
	('SOCKET', NULL, '/run/mysqld/mysqld.sock', 'CONFIG', '', 'GLOBAL', 'VARCHAR', 'Socket file to use for connection', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
	('FOREIGN_KEY_CHECKS', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'If set to 1 (the default) foreign key constraints (including ON UPDATE and ON DELETE behavior) InnoDB tables are checked, while if set to 0, they are not checked. 0 is not recommended for normal use, though it can be useful in situations where you know the data is consistent, but want to reload data in a different order from that that specified by parent/child relationships. Setting this variable to 1 does not retrospectively check for inconsistencies introduced while set to 0.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL, NULL),
	('VERSION_SSL_LIBRARY', NULL, 'OpenSSL 3.0.16 11 Feb 2025', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Version of the used SSL library', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('INNODB_MONITOR_RESET', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Reset a monitor counter', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED', NULL),
	('WSREP_START_POSITION', NULL, '00000000-0000-0000-0000-000000000000:-1', 'COMPILE-TIME', '00000000-0000-0000-0000-000000000000:-1', 'GLOBAL', 'VARCHAR', 'global transaction position to start from ', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_STATS_AUTO_RECALC', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'InnoDB automatic recalculation of persistent statistics enabled for all tables unless overridden at table level (automatic recalculation is only done when InnoDB decides that the table has changed too much and needs a new statistics)', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('WSREP_MAX_WS_ROWS', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'Max number of rows in write set', '0', '1048576', '1', NULL, 'NO', 'REQUIRED', NULL),
	('ROWID_MERGE_BUFF_SIZE', '8388608', '8388608', 'COMPILE-TIME', '8388608', 'SESSION', 'BIGINT UNSIGNED', 'The size of the buffers used [NOT] IN evaluation via partial matching', '0', '9223372036854775807', '1', NULL, 'NO', 'REQUIRED', NULL),
	('WAIT_TIMEOUT', '28800', '28800', 'COMPILE-TIME', '28800', 'SESSION', 'BIGINT UNSIGNED', 'The number of seconds the server waits for activity on a connection before closing it', '1', '31536000', '1', NULL, 'NO', 'REQUIRED', NULL),
	('BINLOG_GTID_INDEX', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Enable the creation of a GTID index for every binlog file, and the use of such index for speeding up GTID lookup in the binlog.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('WSREP_NODE_ADDRESS', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Specifies the node\'s network address, in the format ip address[:port]. Used in situations where autoguessing is not reliable. As of MariaDB 10.1.8, supports IPv6.', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_FATAL_SEMAPHORE_WAIT_THRESHOLD', NULL, '600', 'COMPILE-TIME', '600', 'GLOBAL', 'BIGINT UNSIGNED', 'Maximum number of seconds that semaphore times out in InnoDB.', '1', '4294967295', '0', NULL, 'YES', 'REQUIRED', NULL),
	('SSL_CA', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'CA file in PEM format (check OpenSSL docs, implies --ssl)', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
	('THREAD_STACK', NULL, '299008', 'COMPILE-TIME', '299008', 'GLOBAL', 'BIGINT UNSIGNED', 'The stack size for each thread', '131072', '18446744073709551615', '1024', NULL, 'YES', 'REQUIRED', NULL),
	('WSREP_SST_DONOR_REJECTS_QUERIES', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Reject client queries when donating state snapshot transfer', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('INNODB_FT_SORT_PLL_DEGREE', NULL, '2', 'COMPILE-TIME', '2', 'GLOBAL', 'BIGINT UNSIGNED', 'InnoDB Fulltext search parallel sort degree, will round up to nearest power of 2 number', '1', '16', '0', NULL, 'YES', 'REQUIRED', NULL),
	('SQL_NOTES', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'If set to 1, the default, warning_count is incremented each time a Note warning is encountered. If set to 0, Note warnings are not recorded. mysqldump has outputs to set this variable to 0 so that no unnecessary increments occur when data is reloaded. See also note_verbosity, which allows one to define with notes are sent.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL, NULL),
	('SESSION_TRACK_TRANSACTION_INFO', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'ENUM', 'Track changes to the transaction attributes. OFF to disable; STATE to track just transaction state (Is there an active transaction? Does it have any data? etc.); CHARACTERISTICS to track transaction state and report all statements needed to start a transaction with the same characteristics (isolation level, read only/read write,snapshot - but not any work done / data modified within the transaction).', NULL, NULL, NULL, 'OFF,STATE,CHARACTERISTICS', 'NO', 'REQUIRED', NULL),
	('WSREP_MAX_WS_SIZE', NULL, '2147483647', 'COMPILE-TIME', '2147483647', 'GLOBAL', 'BIGINT UNSIGNED', 'Max write set size (bytes)', '1024', '2147483647', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_FILL_FACTOR', NULL, '100', 'COMPILE-TIME', '100', 'GLOBAL', 'INT UNSIGNED', 'Percentage of B-tree page filled during bulk insert', '10', '100', '0', NULL, 'NO', 'REQUIRED', NULL),
	('GTID_SEQ_NO', '0', NULL, 'COMPILE-TIME', '0', 'SESSION ONLY', 'BIGINT UNSIGNED', 'Internal server usage, for replication with global transaction id. When set, next event group logged to the binary log will use this sequence number, not generate a new one, thus allowing to preserve master\'s GTID in slave\'s binlog.', '0', '18446744073709551615', '1', NULL, 'NO', NULL, NULL),
	('INNODB_ADAPTIVE_FLUSHING', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Attempt flushing dirty pages to avoid IO bursts at checkpoints.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'NONE', NULL),
	('SQL_BUFFER_RESULT', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'If set to 1 (0 is default), results from SELECT statements are always placed into temporary tables. This can help the server when it takes a long time to send the results to the client by allowing the table locks to be freed early.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL, NULL),
	('INNODB_FILE_PER_TABLE', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Stores each InnoDB table to an .ibd file in the database dir.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'NONE', NULL),
	('PERFORMANCE_SCHEMA_MAX_DIGEST_LENGTH', NULL, '1024', 'COMPILE-TIME', '1024', 'GLOBAL', 'BIGINT', 'Maximum length considered for digest text, when stored in performance_schema tables.', '0', '1048576', '1', NULL, 'YES', 'REQUIRED', NULL),
	('EXTRA_PORT', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT UNSIGNED', 'Extra port number to use for tcp connections in a one-thread-per-connection manner. 0 means don\'t use another port', '0', '65535', '1', NULL, 'YES', 'REQUIRED', NULL),
	('TRANSACTION_ISOLATION', 'REPEATABLE-READ', 'REPEATABLE-READ', 'COMPILE-TIME', 'REPEATABLE-READ', 'SESSION', 'ENUM', 'Default transaction isolation level', NULL, NULL, NULL, 'READ-UNCOMMITTED,READ-COMMITTED,REPEATABLE-READ,SERIALIZABLE', 'NO', NULL, NULL),
	('INNODB_LOG_CHECKPOINT_NOW', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Write back dirty pages from the buffer pool and update the log checkpoint', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('BINLOG_CACHE_SIZE', NULL, '32768', 'COMPILE-TIME', '32768', 'GLOBAL', 'BIGINT UNSIGNED', 'The size of the transactional cache for updates to transactional engines for the binary log. If you often use transactions containing many statements, you can increase this to get more performance', '4096', '18446744073709551615', '4096', NULL, 'NO', 'REQUIRED', NULL),
	('THREAD_POOL_PRIO_KICKUP_TIMER', NULL, '1000', 'COMPILE-TIME', '1000', 'GLOBAL', 'INT UNSIGNED', 'The number of milliseconds before a dequeued low-priority statement is moved to the high-priority queue', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
	('LOG_BIN_COMPRESS_MIN_LEN', NULL, '256', 'COMPILE-TIME', '256', 'GLOBAL', 'INT UNSIGNED', 'Minimum length of sql statement(in statement mode) or record(in row mode)that can be compressed.', '10', '1024', '1', NULL, 'NO', 'OPTIONAL', NULL),
	('INNODB_DATA_HOME_DIR', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'The common part for InnoDB table spaces.', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
