	('INNODB_READ_IO_THREADS', NULL, '4', 'COMPILE-TIME', '4', 'GLOBAL', 'INT UNSIGNED', 'Number of background read I/O threads in InnoDB.', '1', '64', '0', NULL, 'NO', 'REQUIRED', NULL),
	('WSREP_LOAD_DATA_SPLITTING', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'To commit LOAD DATA transaction after every 10K rows inserted (deprecated)', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
