	('INNODB_UNDO_DIRECTORY', NULL, './', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Directory where undo tablespace files live, this path can be absolute.', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
	('PERFORMANCE_SCHEMA_HOSTS_SIZE', NULL, '-1', 'COMPILE-TIME', '-1', 'GLOBAL', 'BIGINT', 'Maximum number of instrumented hosts. Use 0 to disable, -1 for automated sizing.', '-1', '1048576', '1', NULL, 'YES', 'REQUIRED', NULL),
	('LOG_BIN_BASENAME', NULL, '', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'The full path of the binary log file names, excluding the extension.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
