	('INNODB_FT_RESULT_CACHE_LIMIT', NULL, '2000000000', 'COMPILE-TIME', '2000000000', 'GLOBAL', 'BIGINT UNSIGNED', 'InnoDB Fulltext search query result cache limit in bytes', '1000000', '18446744073709551615', '0', NULL, 'NO', 'REQUIRED', NULL),
	('SKIP_PARALLEL_REPLICATION', 'OFF', NULL, 'COMPILE-TIME', 'OFF', 'SESSION ONLY', 'BOOLEAN', 'If set when a transaction is written to the binlog, parallel apply of that transaction will be avoided on a slave where slave_parallel_mode is not "aggressive". Can be used to avoid unnecessary rollback and retry for transactions that are likely to cause a conflict if replicated in parallel.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL, NULL),
	('WSREP_SYNC_WAIT', '0', '0', 'COMPILE-TIME', '0', 'SESSION', 'INT UNSIGNED', 'Ensure "synchronous" read view before executing an operation of the type specified by bitmask: 1 - READ(includes SELECT, SHOW and BEGIN/START TRANSACTION); 2 - UPDATE and DELETE; 4 - INSERT and REPLACE', '0', '15', '1', NULL, 'NO', 'OPTIONAL', NULL),
	('WSREP_GTID_MODE', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Automatically update the (joiner) node\'s wsrep_gtid_domain_id value with that of donor\'s (received during state transfer) and use it in place of gtid_domain_id for all galera transactions. When OFF (default), wsrep_gtid_domain_id is simply ignored (backward compatibility).', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('SLAVE_PARALLEL_MAX_QUEUED', NULL, '131072', 'COMPILE-TIME', '131072', 'GLOBAL', 'BIGINT UNSIGNED', 'Limit on how much memory SQL threads should use per parallel replication thread when reading ahead in the relay log looking for opportunities for parallel replication. Only used when --slave-parallel-threads > 0.', '0', '2147483647', '1', NULL, 'NO', 'REQUIRED', NULL),
	('SLAVE_EXEC_MODE', NULL, 'STRICT', 'COMPILE-TIME', 'STRICT', 'GLOBAL', 'ENUM', 'How replication events should be executed. Legal values are STRICT (default) and IDEMPOTENT. In IDEMPOTENT mode, replication will not stop for operations that are idempotent. For example, in row based replication attempts to delete rows that doesn\'t exist will be ignored. In STRICT mode, replication will stop on any unexpected difference between the master and the slave.', NULL, NULL, NULL, 'STRICT,IDEMPOTENT', 'NO', 'REQUIRED', NULL),
	('INNODB_ENCRYPTION_ROTATE_KEY_AGE', NULL, '1', 'COMPILE-TIME', '1', 'GLOBAL', 'INT UNSIGNED', 'Key rotation - re-encrypt in background all pages that were encrypted with a key that many (or more) versions behind. Value 0 indicates that key rotation is disabled.', '0', '4294967295', '0', NULL, 'NO', 'REQUIRED', NULL),
	('WSREP_NODE_INCOMING_ADDRESS', NULL, 'AUTO', 'COMPILE-TIME', 'AUTO', 'GLOBAL', 'VARCHAR', 'Client connection address', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED', NULL),
	('OPTIMIZER_TRACE', 'enabled=off', 'enabled=off', 'COMPILE-TIME', 'enabled=off', 'SESSION', 'FLAGSET', 'Controls tracing of the Optimizer: optimizer_trace=option=val[,option=val...], where option is one of {enabled} and val is one of {on, off, default}', NULL, NULL, NULL, 'enabled,default', 'NO', 'REQUIRED', NULL),
	('AUTO_INCREMENT_INCREMENT', '1', '1', 'COMPILE-TIME', '1', 'SESSION', 'BIGINT UNSIGNED', 'Auto-increment columns are incremented by this', '1', '65535', '1', NULL, 'NO', 'OPTIONAL', NULL),
	('REQUIRE_SECURE_TRANSPORT', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'When this option is enabled, connections attempted using insecure transport will be rejected. Secure transports are SSL/TLS, Unix sockets or named pipes.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('BINLOG_IGNORE_DB', NULL, '', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Tells the primary that updates to the given database should not be logged to the binary log.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('INNODB_READ_AHEAD_THRESHOLD', NULL, '56', 'COMPILE-TIME', '56', 'GLOBAL', 'BIGINT UNSIGNED', 'Number of pages that must be accessed sequentially for InnoDB to trigger a readahead.', '0', '64', '0', NULL, 'NO', 'REQUIRED', NULL),
	('REPLICATE_DO_DB', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Tell the slave to restrict replication to updates of tables whose names appear in the comma-separated list. For statement-based replication, only the default database (that is, the one selected by USE) is considered, not any explicitly mentioned tables in the query. For row-based replication, the actual names of table(s) being updated are checked.', NULL, NULL, NULL, NULL, 'NO', NULL, NULL),
	('INNODB_READ_ONLY', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Start InnoDB in read only mode (off by default)', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL', NULL),
