	('HAVE_RTREE_KEYS', NULL, 'YES', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'If RTREE indexes (used for spatial indexes) are available, will be set to YES, otherwise will be set to NO.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('AUTOCOMMIT', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'If set to 1, the default, all queries are committed immediately. If set to 0, they are only committed upon a COMMIT statement, or rolled back with a ROLLBACK statement. If autocommit is set to 0, and then changed to 1, all open transactions are immediately committed.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL, NULL),
	('ERROR_COUNT', '0', NULL, 'COMPILE-TIME', NULL, 'SESSION ONLY', 'BIGINT UNSIGNED', 'The number of errors that resulted from the last statement that generated messages', '0', '18446744073709551615', '1', NULL, 'YES', NULL, NULL),
	('EQ_RANGE_INDEX_DIVE_LIMIT', '200', '200', 'COMPILE-TIME', '200', 'SESSION', 'INT UNSIGNED', 'The optimizer will use existing index statistics instead of doing index dives for equality ranges if the number of equality ranges for the index is larger than or equal to this number. If set to 0, index dives are always used.', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
	('MASTER_VERIFY_CHECKSUM', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Force checksum verification of logged events in the binary log before sending them to slaves or printing them in the output of SHOW BINLOG EVENTS', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
