	('IN_PREDICATE_CONVERSION_THRESHOLD', '1000', '1000', 'COMPILE-TIME', '1000', 'SESSION', 'INT UNSIGNED', 'The minimum number of scalar elements in the value list of IN predicate that triggers its conversion to IN subquery. Set to 0 to disable the conversion.', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
	('OPEN_FILES_LIMIT', NULL, '49055', 'AUTO', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'If this is not 0, then mysqld will use this value to reserve file descriptors to use with setrlimit(). If this value is 0 or autoset then mysqld will reserve max_connections*5 or max_connections + table_cache*2 (whichever is larger) number of file descriptors', '0', '4294967295', '1', NULL, 'YES', 'REQUIRED', NULL),
	('TRANSACTION_PREALLOC_SIZE', '4096', '4096', 'COMPILE-TIME', '4096', 'SESSION', 'BIGINT UNSIGNED', 'Persistent buffer for transactions to be stored in binary log', '1024', '134217728', '1024', NULL, 'NO', 'REQUIRED', NULL),
	('SQL_LOG_OFF', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'If set to 1 (0 is the default), no logging to the general query log is done for the client. Only clients with the SUPER privilege can update this variable.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL, NULL),
	('VERSION_COMPILE_OS', NULL, 'debian-linux-gnu', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Operating system that MariaDB was built on, for example debian-linux-gnu.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
