	('WSREP_CLUSTER_NAME', NULL, 'my_wsrep_cluster', 'COMPILE-TIME', 'my_wsrep_cluster', 'GLOBAL', 'VARCHAR', 'Name for the cluster', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED', NULL),
	('SLAVE_SQL_VERIFY_CHECKSUM', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Force checksum verification of replication events after reading them from relay log. Note: Events are always checksum-verified by slave on receiving them from the network before writing them to the relay log', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('MAX_LENGTH_FOR_SORT_DATA', '1024', '1024', 'COMPILE-TIME', '1024', 'SESSION', 'BIGINT UNSIGNED', 'Max number of bytes in sorted records', '4', '8388608', '1', NULL, 'NO', 'REQUIRED', NULL),
	('IDLE_READONLY_TRANSACTION_TIMEOUT', '0', '0', 'COMPILE-TIME', '0', 'SESSION', 'INT UNSIGNED', 'The number of seconds the server waits for read-only idle transaction', '0', '31536000', '1', NULL, 'NO', 'REQUIRED', NULL),
	('MYISAM_STATS_METHOD', 'NULLS_UNEQUAL', 'NULLS_UNEQUAL', 'COMPILE-TIME', 'NULLS_UNEQUAL', 'SESSION', 'ENUM', 'Specifies how MyISAM index statistics collection code should treat NULLs. Possible values of name are NULLS_UNEQUAL (default behavior for 4.1 and later), NULLS_EQUAL (emulate 4.0 behavior), and NULLS_IGNORED', NULL, NULL, NULL, 'NULLS_UNEQUAL,NULLS_EQUAL,NULLS_IGNORED', 'NO', 'REQUIRED', NULL),
	('REPLICATE_EVENTS_MARKED_FOR_SKIP', NULL, 'REPLICATE', 'COMPILE-TIME', 'REPLICATE', 'GLOBAL', 'ENUM', 'Whether the slave should replicate events that were created with @@skip_replication=1 on the master. Default REPLICATE (no events are skipped). Other values are FILTER_ON_SLAVE (events will be sent by the master but ignored by the slave) and FILTER_ON_MASTER (events marked with @@skip_replication=1 will be filtered on the master and never be sent to the slave).', NULL, NULL, NULL, 'REPLICATE,FILTER_ON_SLAVE,FILTER_ON_MASTER', 'NO', 'REQUIRED', NULL),
	('INNODB_COMPRESSION_LEVEL', NULL, '6', 'COMPILE-TIME', '6', 'GLOBAL', 'INT UNSIGNED', 'Compression level used for zlib compression.  0 is no compression, 1 is fastest, 9 is best compression and default is 6.', '0', '9', '0', NULL, 'NO', 'REQUIRED', NULL),
	('INTERACTIVE_TIMEOUT', '28800', '28800', 'COMPILE-TIME', '28800', 'SESSION', 'BIGINT UNSIGNED', 'The number of seconds the server waits for activity on an interactive connection before closing it', '1', '31536000', '1', NULL, 'NO', 'REQUIRED', NULL),
	('SECURE_AUTH', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Disallow authentication for accounts that have old (pre-4.1) passwords', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
