	('MAX_ERROR_COUNT', '64', '64', 'COMPILE-TIME', '64', 'SESSION', 'BIGINT UNSIGNED', 'Max number of errors/warnings to store for a statement', '0', '65535', '1', NULL, 'NO', 'REQUIRED', NULL),
	('SLAVE_LOAD_TMPDIR', NULL, '/tmp', 'AUTO', '', 'GLOBAL', 'VARCHAR', 'The location where the slave should put its temporary files when replicating a LOAD DATA INFILE command', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
	('FT_MIN_WORD_LEN', NULL, '4', 'COMPILE-TIME', '4', 'GLOBAL', 'BIGINT UNSIGNED', 'The minimum length of the word to be included in a FULLTEXT index. Note: FULLTEXT indexes must be rebuilt after changing this variable', '1', '84', '1', NULL, 'YES', 'REQUIRED', NULL),
	('TCP_NODELAY', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'Set option TCP_NODELAY (disable Nagle\'s algorithm) on socket', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('WSREP_FORCED_BINLOG_FORMAT', NULL, 'NONE', 'COMPILE-TIME', 'NONE', 'GLOBAL', 'ENUM', 'binlog format to take effect over user\'s choice', NULL, NULL, NULL, 'MIXED,STATEMENT,ROW,NONE', 'NO', 'REQUIRED', NULL),
	('SLAVE_RUN_TRIGGERS_FOR_RBR', NULL, 'NO', 'COMPILE-TIME', 'NO', 'GLOBAL', 'ENUM', 'Modes for how triggers in row-base replication on slave side will be executed. Legal values are NO (default), YES, LOGGING and ENFORCE. NO means that trigger for RBR will not be running on slave. YES and LOGGING means that triggers will be running on slave, if there was not triggers running on the master for the statement. LOGGING also means results of that the executed triggers work will be written to the binlog. ENFORCE means that triggers will always be run on the slave, even if there are triggers on the master. ENFORCE implies LOGGING.', NULL, NULL, NULL, 'NO,YES,LOGGING,ENFORCE', 'NO', 'REQUIRED', NULL),
	('DEFAULT_PASSWORD_LIFETIME', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT UNSIGNED', 'This defines the global password expiration policy. 0 means automatic password expiration is disabled. If the value is a positive integer N, the passwords must be changed every N days. This behavior can be overridden using the password expiration options in ALTER USER.', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
	('SLAVE_DOMAIN_PARALLEL_THREADS', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'Maximum number of parallel threads to use on slave for events in a single replication domain. When using multiple domains, this can be used to limit a single domain from grabbing all threads and thus stalling other domains. The default of 0 means to allow a domain to grab as many threads as it wants, up to the value of slave_parallel_threads.', '0', '16383', '1', NULL, 'NO', 'REQUIRED', NULL),
	('MYISAM_MMAP_SIZE', NULL, '18446744073709551615', 'COMPILE-TIME', '18446744073709551615', 'GLOBAL', 'BIGINT UNSIGNED', 'Restricts the total memory used for memory mapping of MySQL tables', '7', '18446744073709551615', '1', NULL, 'YES', 'REQUIRED', NULL),
	('INNODB_SNAPSHOT_ISOLATION', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'Use snapshot isolation (write-write conflict detection).', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('INNODB_FT_ENABLE_STOPWORD', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'Create FTS index with stopword.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('INNODB_FT_ENABLE_DIAG_PRINT', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Whether to enable additional FTS diagnostic printout ', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
