	('HAVE_SYMLINK', NULL, 'YES', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'If symbolic link support is enabled, will be set to YES, otherwise will be set to NO. Required for the INDEX DIRECTORY and DATA DIRECTORY table options (see CREATE TABLE) and Windows symlink support. Will be set to DISABLED if the server is started with the --skip-symbolic-links option.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('HAVE_COMPRESS', NULL, 'YES', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'If the zlib compression library is accessible to the server, this will be set to YES, otherwise it will be NO. The COMPRESS() and UNCOMPRESS() functions will only be available if set to YES.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('KEY_CACHE_BLOCK_SIZE', NULL, '1024', 'COMPILE-TIME', '1024', 'GLOBAL', 'BIGINT UNSIGNED', 'The default size of key cache blocks', '512', '16384', '512', NULL, 'NO', 'REQUIRED', NULL),
	('ARIA_LOG_DIR_PATH', NULL, '/var/lib/mysql/', 'COMPILE-TIME', '/var/lib/mysql/', 'GLOBAL', 'VARCHAR', 'Path to the directory where to store transactional log', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
	('INNODB_FLUSH_NEIGHBORS', NULL, '1', 'COMPILE-TIME', '1', 'GLOBAL', 'BIGINT UNSIGNED', 'Set to 0 (don\'t flush neighbors from buffer pool), 1 (flush contiguous neighbors from buffer pool) or 2 (flush neighbors from buffer pool), when flushing a block', '0', '2', '0', NULL, 'NO', 'OPTIONAL', NULL),
	('INNODB_FLUSH_METHOD', NULL, 'O_DIRECT', 'COMPILE-TIME', 'O_DIRECT', 'GLOBAL', 'ENUM', 'With which method to flush data.', NULL, NULL, NULL, 'fsync,O_DSYNC,littlesync,nosync,O_DIRECT,O_DIRECT_NO_FSYNC', 'YES', 'REQUIRED', NULL),
	('SECURE_TIMESTAMP', NULL, 'NO', 'COMPILE-TIME', 'NO', 'GLOBAL', 'ENUM', 'Restricts direct setting of a session timestamp. Possible levels are: YES - timestamp cannot deviate from the system clock, REPLICATION - replication thread can adjust timestamp to match the master\'s, SUPER - a user with this privilege and a replication thread can adjust timestamp, NO - historical behavior, anyone can modify session timestamp', NULL, NULL, NULL, 'NO,SUPER,REPLICATION,YES', 'YES', 'REQUIRED', NULL),
	('INNODB_BUFFER_POOL_SIZE_MAX', NULL, '100629741568', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'Maximum innodb_buffer_pool_size', '0', '18446744073701163008', '8388608', NULL, 'YES', 'REQUIRED', NULL),
	('BINLOG_ROW_IMAGE', 'FULL', 'FULL', 'COMPILE-TIME', 'FULL', 'SESSION', 'ENUM', 'Controls whether rows should be logged in \'FULL\', \'FULL_NODUP\', \'NOBLOB\' or \'MINIMAL\' formats. \'FULL\', means that all columns in the before and after image are logged. \'FULL_NODUP\', means that all columns are logged in before image, but only changed columns or all columns of inserted record are logged in after image, \'NOBLOB\', means that mysqld avoids logging blob columns whenever possible (eg, blob column was not changed or is not part of primary key). \'MINIMAL\', means that a PK equivalent (PK columns or full row if there is no PK in the table) is logged in the before image, and only changed columns are logged in the after image. (Default: FULL).', NULL, NULL, NULL, 'MINIMAL,NOBLOB,FULL,FULL_NODUP', 'NO', 'REQUIRED', NULL),
	('MYISAM_USE_MMAP', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Use memory mapping for reading and writing MyISAM tables', NULL, NULL, NULL, 'OFF,ON', 'NO', 'NONE', NULL),
	('MAX_BINLOG_TOTAL_SIZE', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'Maximum space to use for all binary logs. Extra logs are deleted on server start, log rotation, FLUSH LOGS or when writing to binlog. Default is 0, which means no size restrictions. See also slave_connections_needed_for_purge', '0', '18446744073709551615', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_BUFFER_POOL_LOAD_AT_STARTUP', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Load the buffer pool from a file named @@innodb_buffer_pool_filename', NULL, NULL, NULL, 'OFF,ON', 'YES', 'REQUIRED', NULL),
	('WSREP_RECOVER', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Recover database state after crash and exit', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL', NULL),
	('REPLICATE_ANNOTATE_ROW_EVENTS', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Tells the slave to write annotate rows events received from the master to its own binary log. Ignored if log_slave_updates is not set', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL', NULL),
	('GTID_CLEANUP_BATCH_SIZE', NULL, '64', 'COMPILE-TIME', '64', 'GLOBAL', 'INT UNSIGNED', 'Normally does not need tuning. How many old rows must accumulate in the mysql.gtid_slave_pos table before a background job will be run to delete them. Can be increased to reduce number of commits if using many different engines with --gtid_pos_auto_engines, or to reduce CPU overhead if using a huge number of different gtid_domain_ids. Can be decreased to reduce number of old rows in the table.', '0', '2147483647', '1', NULL, 'NO', 'REQUIRED', NULL),
	('OPTIMIZER_ROW_LOOKUP_COST', NULL, '0.130839', 'COMPILE-TIME', '0.130839', 'GLOBAL', 'DOUBLE', 'Cost of finding a row based on a rowid or a clustered key.', '0', '1000', NULL, NULL, 'NO', 'REQUIRED', NULL),
	('OPTIMIZER_SCAN_SETUP_COST', '10.000000', '10.000000', 'COMPILE-TIME', '10.000000', 'SESSION', 'DOUBLE', 'Extra cost added to TABLE and INDEX scans to get optimizer to prefer index lookups.', '0', '100000000', NULL, NULL, 'NO', 'REQUIRED', NULL),
	('LOG_SLAVE_UPDATES', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Tells the slave to log the updates from the slave thread to the binary log. You will need to turn it on if you plan to daisy-chain the slaves.', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL', NULL),
	('MAX_SEEKS_FOR_KEY', '4294967295', '4294967295', 'COMPILE-TIME', '4294967295', 'SESSION', 'BIGINT UNSIGNED', 'Limit assumed max number of seeks when looking up rows based on a key', '1', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
