	('KEY_CACHE_SEGMENTS', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'BIGINT UNSIGNED', 'The number of segments in a key cache', '0', '64', '1', NULL, 'NO', 'REQUIRED', NULL),
	('PROTOCOL_VERSION', NULL, '10', 'COMPILE-TIME', NULL, 'GLOBAL', 'INT UNSIGNED', 'The version of the client/server protocol used by the MariaDB server', '0', '4294967295', '1', NULL, 'YES', NULL, NULL),
