	('MAX_BINLOG_CACHE_SIZE', NULL, '18446744073709547520', 'COMPILE-TIME', '18446744073709547520', 'GLOBAL', 'BIGINT UNSIGNED', 'Sets the total size of the transactional cache', '4096', '18446744073709551615', '4096', NULL, 'NO', 'REQUIRED', NULL),
