	('SLAVE_TRANSACTION_RETRIES', NULL, '10', 'COMPILE-TIME', '10', 'GLOBAL', 'BIGINT UNSIGNED', 'Number of times the slave SQL thread will retry a transaction in case it failed with a deadlock, elapsed lock wait timeout or listed in slave_transaction_retry_errors, before giving up and stopping', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
	('OPTIMIZER_SEARCH_DEPTH', '62', '62', 'COMPILE-TIME', '62', 'SESSION', 'BIGINT UNSIGNED', 'Maximum depth of search performed by the query optimizer. Values larger than the number of relations in a query result in better query plans, but take longer to compile a query. Values smaller than the number of tables in a relation result in faster optimization, but may produce very bad query plans. If set to 0, the system will automatically pick a reasonable value.', '0', '62', '1', NULL, 'NO', 'REQUIRED', NULL),
	('OPTIMIZER_INDEX_BLOCK_COPY_COST', NULL, '0.035600', 'COMPILE-TIME', '0.035600', 'GLOBAL', 'DOUBLE', 'Cost of copying a key block from the cache to intern storage as part of an index scan.', '0', '1000', NULL, NULL, 'NO', 'REQUIRED', NULL),
	('TCP_KEEPALIVE_TIME', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT', 'Timeout, in seconds, with no activity until the first TCP keep-alive packet is sent.If set to 0, system dependent default is used.', '0', '2147483', '1', NULL, 'NO', 'REQUIRED', NULL),
