	('LOG_SLOW_SLAVE_STATEMENTS', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'Log slow statements executed by slave thread to the slow log if it is open. Resets or sets the option \'slave\' in log_slow_disabled_statements', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('INNODB_DATA_FILE_PATH', NULL, 'ibdata1:12M:autoextend', 'COMPILE-TIME', 'ibdata1:12M:autoextend', 'GLOBAL', 'VARCHAR', 'Path to individual files and their sizes.', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
	('REPLICATE_IGNORE_DB', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Tell the slave to restrict replication to updates of tables whose names do not appear in the comma-separated list. For statement-based replication, only the default database (that is, the one selected by USE) is considered, not any explicitly mentioned tables in the query. For row-based replication, the actual names of table(s) being updated are checked.', NULL, NULL, NULL, NULL, 'NO', NULL, NULL),
	('IGNORE_BUILTIN_INNODB', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Disable initialization of builtin InnoDB plugin', NULL, NULL, NULL, 'OFF,ON', 'YES', 'OPTIONAL', NULL),
	('REPLICATE_IGNORE_TABLE', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Tells the slave thread not to replicate any statement that updates the specified table, even if any other tables might be updated by the same statement.', NULL, NULL, NULL, NULL, 'NO', NULL, NULL),
	('WSREP_DIRTY_READS', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'Allow reads even when the node is not in the primary component.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('WSREP_SST_AUTH', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Authentication for SST connection', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED', NULL),
	('COLUMN_COMPRESSION_THRESHOLD', '100', '100', 'COMPILE-TIME', '100', 'SESSION', 'INT UNSIGNED', 'Minimum column data length eligible for compression', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_CHECKSUM_ALGORITHM', NULL, 'full_crc32', 'COMPILE-TIME', 'full_crc32', 'GLOBAL', 'ENUM', 'The algorithm InnoDB uses for page checksumming. Possible values are FULL_CRC32 for new files, always use CRC-32C; for old, see CRC32 below; STRICT_FULL_CRC32 for new files, always use CRC-32C; for old, see STRICT_CRC32 below; CRC32 write crc32, allow previously used algorithms to match when reading; STRICT_CRC32 write crc32, do not allow other algorithms to match when reading; New files created with full_crc32 are readable by MariaDB 10.4.3+', NULL, NULL, NULL, 'crc32,strict_crc32,full_crc32,strict_full_crc32', 'NO', 'REQUIRED', NULL),
	('ALTER_ALGORITHM', 'DEFAULT', 'DEFAULT', 'COMPILE-TIME', 'DEFAULT', 'SESSION', 'ENUM', 'Specify the alter table algorithm', NULL, NULL, NULL, 'DEFAULT,COPY,INPLACE,NOCOPY,INSTANT', 'NO', 'OPTIONAL', NULL),
	('ARIA_LOG_PURGE_TYPE', NULL, 'immediate', 'COMPILE-TIME', 'immediate', 'GLOBAL', 'ENUM', 'Specifies how Aria transactional log will be purged', NULL, NULL, NULL, 'immediate,external,at_flush', 'NO', 'REQUIRED', NULL),
	('SQL_LOG_BIN', 'ON', 'ON', 'COMPILE-TIME', 'ON', 'SESSION', 'BOOLEAN', 'If set to 0 (1 is the default), no logging to the binary log is done for the client. Only clients with the SUPER privilege can update this variable. Can have unintended consequences if set globally, see SET SQL_LOG_BIN. Starting MariaDB 10.1.7, this variable does not affect the replication of events in a Galera cluster.', NULL, NULL, NULL, 'OFF,ON', 'NO', NULL, NULL),
	('MYSQL56_TEMPORAL_FORMAT', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'Use MySQL-5.6 (instead of MariaDB-5.3) format for TIME, DATETIME, TIMESTAMP columns.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('SERVER_UID', NULL, 'JFcu7jJHLOeAJQEw1hKdQdJEUUo=', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Automatically calculated server unique id hash', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('ARIA_BLOCK_SIZE', NULL, '8192', 'COMPILE-TIME', '8192', 'GLOBAL', 'BIGINT UNSIGNED', 'Block size to be used for Aria index pages.', '4096', '32768', '1024', NULL, 'YES', 'REQUIRED', NULL),
	('WSREP_SST_DONOR', NULL, '', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'preferred donor node for the SST', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED', NULL),
	('WSREP_SR_STORE', NULL, 'table', 'COMPILE-TIME', 'table', 'GLOBAL', 'ENUM', 'Storage for streaming replication fragments', NULL, NULL, NULL, 'none,table', 'YES', 'REQUIRED', NULL),
	('TMPDIR', NULL, '/tmp', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'Path for temporary files. Several paths may be specified, separated by a colon (:), in this case they are used in a round-robin fashion', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
	('THREAD_POOL_SIZE', NULL, '24', 'AUTO', '8', 'GLOBAL', 'INT UNSIGNED', 'Number of thread groups in the pool. This parameter is roughly equivalent to maximum number of concurrently executing threads (threads in a waiting state do not count as executing).', '1', '100000', '1', NULL, 'NO', 'REQUIRED', NULL),
	('WSREP_DESYNC', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'To desynchronize the node from the cluster', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('INNODB_DATA_FILE_BUFFERING', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Whether the file system cache for data files is enabled', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('SESSION_TRACK_STATE_CHANGE', 'OFF', 'OFF', 'COMPILE-TIME', 'OFF', 'SESSION', 'BOOLEAN', 'Track changes to the session state.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('MAX_ALLOWED_PACKET', '1073741824', '1073741824', 'CONFIG', '16777216', 'SESSION', 'BIGINT UNSIGNED', 'Max packet length to send to or receive from the server', '1024', '1073741824', '1024', NULL, 'NO', 'REQUIRED', NULL),
	('TABLE_OPEN_CACHE_INSTANCES', NULL, '8', 'COMPILE-TIME', '8', 'GLOBAL', 'INT UNSIGNED', 'Maximum number of table cache instances', '1', '64', '1', NULL, 'YES', 'REQUIRED', NULL),
	('USERSTAT', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Enables statistics gathering for USER_STATISTICS, CLIENT_STATISTICS, INDEX_STATISTICS and TABLE_STATISTICS tables in the INFORMATION_SCHEMA', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('RELAY_LOG_INFO_FILE', NULL, 'relay-log.info', 'COMPILE-TIME', '', 'GLOBAL', 'VARCHAR', 'The location and name of the file that remembers where the SQL replication thread is in the relay logs.', NULL, NULL, NULL, NULL, 'YES', 'REQUIRED', NULL),
	('SESSION_TRACK_SYSTEM_VARIABLES', 'autocommit,character_set_client,character_set_connection,character_set_results,redirect_url,time_zone', 'autocommit,character_set_client,character_set_connection,character_set_results,redirect_url,time_zone', 'COMPILE-TIME', 'autocommit,character_set_client,character_set_connection,character_set_results,redirect_url,time_zone', 'SESSION', 'VARCHAR', 'Track changes in registered system variables. ', NULL, NULL, NULL, NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_AUTOINC_LOCK_MODE', NULL, '1', 'COMPILE-TIME', '1', 'GLOBAL', 'BIGINT', 'The AUTOINC lock modes supported by InnoDB: 0 => Old style AUTOINC locking (for backward compatibility); 1 => New style AUTOINC locking; 2 => No AUTOINC locking (unsafe for SBR)', '0', '2', '0', NULL, 'YES', 'REQUIRED', NULL),
	('ARIA_SYNC_LOG_DIR', NULL, 'NEWFILE', 'COMPILE-TIME', 'NEWFILE', 'GLOBAL', 'ENUM', 'Controls syncing directory after log file growth and new file creation', NULL, NULL, NULL, 'NEVER,NEWFILE,ALWAYS', 'NO', 'REQUIRED', NULL),
	('GTID_DOMAIN_ID', '0', '0', 'COMPILE-TIME', '0', 'SESSION', 'INT UNSIGNED', 'Used with global transaction ID to identify logically independent replication streams. When events can propagate through multiple parallel paths (for example multiple masters), each independent source server must use a distinct domain_id. For simple tree-shaped replication topologies, it can be left at its default, 0.', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_FORCE_PRIMARY_KEY', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'Do not allow creating a table without primary key (off by default)', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('LOWER_CASE_TABLE_NAMES', NULL, '0', 'COMPILE-TIME', '0', 'GLOBAL', 'INT UNSIGNED', 'If set to 1 table names are stored in lowercase on disk and table names will be case-insensitive.  Should be set to 2 if you are using a case insensitive file system', '0', '2', '1', NULL, 'YES', 'OPTIONAL', NULL),
	('RELAY_LOG_PURGE', NULL, 'ON', 'COMPILE-TIME', 'ON', 'GLOBAL', 'BOOLEAN', 'if disabled - do not purge relay logs. if enabled - purge them as soon as they are no more needed.', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL),
	('OPTIMIZER_DISK_READ_RATIO', NULL, '0.020000', 'COMPILE-TIME', '0.020000', 'GLOBAL', 'DOUBLE', 'Chance that we have to do a disk read to find a row or index entry from the engine cache (cache_misses/total_cache_requests).  0.0 means that everything is cached and 1.0 means that nothing is expected to be in the engine cache.', '0', '1', NULL, NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_FT_TOTAL_CACHE_SIZE', NULL, '640000000', 'COMPILE-TIME', '640000000', 'GLOBAL', 'BIGINT UNSIGNED', 'Total memory allocated for InnoDB Fulltext Search cache', '32000000', '1099511627776', '0', NULL, 'NO', 'REQUIRED', NULL),
	('VERSION', NULL, '11.4.7-MariaDB-deb12', 'COMPILE-TIME', NULL, 'GLOBAL', 'VARCHAR', 'Server version number. It may also include a suffix with configuration or build information. -debug indicates debugging support was enabled on the server, and -log indicates at least one of the binary log, general log or slow query log are enabled, for example 10.1.1-MariaDB-mariadb1precise-log.', NULL, NULL, NULL, NULL, 'YES', NULL, NULL),
	('OPTIMIZER_MAX_SEL_ARGS', '16000', '16000', 'COMPILE-TIME', '16000', 'SESSION', 'BIGINT UNSIGNED', 'The maximum number of SEL_ARG objects created when optimizing a range. If more objects would be needed, the range will not be used by the optimizer.', '0', '4294967295', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_FAST_SHUTDOWN', NULL, '1', 'COMPILE-TIME', '1', 'GLOBAL', 'INT UNSIGNED', 'Speeds up the shutdown process of the InnoDB storage engine. Possible values are 0, 1 (faster), 2 (crash-like), 3 (fastest clean).', '0', '3', '0', NULL, 'NO', 'OPTIONAL', NULL),
	('IDLE_TRANSACTION_TIMEOUT', '0', '0', 'COMPILE-TIME', '0', 'SESSION', 'INT UNSIGNED', 'The number of seconds the server waits for idle transaction', '0', '31536000', '1', NULL, 'NO', 'REQUIRED', NULL),
	('INNODB_SYNC_SPIN_LOOPS', NULL, '30', 'COMPILE-TIME', '30', 'GLOBAL', 'BIGINT UNSIGNED', 'Count of spin-loop rounds in InnoDB mutexes (30 by default)', '0', '18446744073709551615', '0', NULL, 'NO', 'REQUIRED', NULL),
	('ARIA_PAGECACHE_AGE_THRESHOLD', NULL, '300', 'COMPILE-TIME', '300', 'GLOBAL', 'BIGINT UNSIGNED', 'This characterizes the number of hits a hot block has to be untouched until it is considered aged enough to be downgraded to a warm block. This specifies the percentage ratio of that number of hits to the total number of blocks in the page cache.', '100', '18446744073709551615', '100', NULL, 'NO', 'REQUIRED', NULL),
	('THREAD_POOL_EXACT_STATS', NULL, 'OFF', 'COMPILE-TIME', 'OFF', 'GLOBAL', 'BOOLEAN', 'If set to 1, provides better statistics in information_schema threadpool tables', NULL, NULL, NULL, 'OFF,ON', 'NO', 'OPTIONAL', NULL);
